import os
import json
import base64
from flask import Flask, request, Response, send_file
from openai import OpenAI

app = Flask(__name__)

client = OpenAI(
    api_key=os.environ.get("HPC_AI_API_KEY", ""),
    base_url="",
)

MODEL = "zai-org/glm-5.1"
MAX_TOKENS = 202000
TEMPERATURE = 0


def build_openai_messages(messages):
    result = []
    result.append({"role": "system", "content": "You are a helpful assistant."})
    for m in messages:
        role = m.get("role", "user")
        content = m.get("content", "")
        attachments = m.get("attachments") or {}
        imgs = attachments.get("imgs") or []
        text_atts = attachments.get("textAtts") or []

        if role == "user":
            parts = []
            if content:
                text_body = content
                if text_atts:
                    for ta in text_atts:
                        name = ta.get("name", "file")
                        file_content = ta.get("content", "")
                        text_body += f"\n\n--- {name} ---\n{file_content}"
                parts.append({"type": "text", "text": text_body})
            elif text_atts:
                text_body = ""
                for ta in text_atts:
                    name = ta.get("name", "file")
                    file_content = ta.get("content", "")
                    text_body += f"--- {name} ---\n{file_content}\n\n"
                parts.append({"type": "text", "text": text_body.strip()})
            for img in imgs:
                data_url = img.get("dataUrl", "")
                if data_url.startswith("data:"):
                    parts.append({"type": "image_url", "image_url": {"url": data_url}})
            if len(parts) == 1 and parts[0]["type"] == "text":
                result.append({"role": "user", "content": parts[0]["text"]})
            elif parts:
                result.append({"role": "user", "content": parts})
            else:
                result.append({"role": "user", "content": ""})
        else:
            result.append({"role": "assistant", "content": content})
    return result


def stream_chat(messages):
    openai_messages = build_openai_messages(messages)
    try:
        stream = client.chat.completions.create(
            model=MODEL,
            messages=openai_messages,
            max_tokens=MAX_TOKENS,
            temperature=TEMPERATURE,
            stream=True,
            extra_body={"thinking": {"type": "enabled", "budget_tokens": 32000}},
        )
        for chunk in stream:
            if not chunk.choices:
                continue
            delta = chunk.choices[0].delta
            reasoning = getattr(delta, "reasoning_content", None)
            content = getattr(delta, "content", None)
            if reasoning:
                yield f"data: {json.dumps({'type': 'thinking', 'content': reasoning})}\n\n"
            if content:
                yield f"data: {json.dumps({'type': 'content', 'content': content})}\n\n"
        yield "data: [DONE]\n\n"
    except Exception as e:
        yield f"data: {json.dumps({'type': 'error', 'message': str(e)})}\n\n"
        yield "data: [DONE]\n\n"


@app.route("/")
def index():
    return send_file("index.html")


@app.route("/chat", methods=["POST"])
def chat():
    data = request.get_json(force=True, silent=True) or {}
    messages = data.get("messages", [])
    return Response(
        stream_chat(messages),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            "Connection": "keep-alive",
        },
    )


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, debug=False)

